/** Generated by scaffold-crud-pages. Query hooks for Questions.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchQuestionsList,
  fetchQuestionsById,
  createQuestions,
  updateQuestions,
  deleteQuestions,
  type FetchQuestionsListParams,
} from '~/services/httpServices/questionsService';
import type { CreateQuestionsRequest, UpdateQuestionsRequest } from '~/types/questions';

const DOMAIN = 'questions';

export function useQuestionsList(params?: FetchQuestionsListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchQuestionsList(params),
  });
}

export function useQuestions(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchQuestionsById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateQuestions() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateQuestionsRequest) => createQuestions(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateQuestions() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateQuestionsRequest }) =>
      updateQuestions(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteQuestions() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteQuestions(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
